package com.orbitalhq.query

import com.orbitalhq.firstRawValue
import com.orbitalhq.testVyne
import io.kotest.core.spec.style.DescribeSpec
import io.kotest.datatest.withData
import io.kotest.matchers.shouldBe
import java.math.BigDecimal

class NumberCalculatorSpec : DescribeSpec({

   describe("calculate number") {
      withData(
         NumberMathScenario("1 + 2", 3),
         NumberMathScenario("2 + -1", 1),
         NumberMathScenario("0 + -1", -1),
         NumberMathScenario("3 - 1", 2),
         NumberMathScenario("3 - -1", 4),
         NumberMathScenario("-2 - -1", -1),
//            NumberMathScenario("1L + 2L", 3L),
         NumberMathScenario("1.5 + 4.0", 5.5.toBigDecimal()),
         NumberMathScenario("1.5 * 4.0", BigDecimal("6.00")),

         // Modulo
         NumberMathScenario("2 % 2", 0),
         NumberMathScenario("2 % 3", 2),
         NumberMathScenario("4 % 3", 1),

         // Mixed types return BigDecimal
         NumberMathScenario("1.5 * 4", 6.0.toBigDecimal()),
//         NumberMathScenario("2L * 4.0", 8.0.toBigDecimal()),
//         NumberMathScenario(
//            "4 / 0.55003", BigDecimal(
//               "7."
//            )
//         ),
         NumberMathScenario("3 / 2", 1.5.toBigDecimal()),

         // BigDecimals
         NumberMathScenario("10.0 * 5.0", BigDecimal("50.00")),
         NumberMathScenario("10.0- 5.0", BigDecimal.valueOf(5.0)),
         NumberMathScenario("10.0 / 5.0", BigDecimal("2")) // duplicated in original
      ) { (expression, expected) ->
         val (vyne, _) = testVyne("")
         vyne.query("""find { $expression }""")
            .firstRawValue()
            .shouldBe(expected)
      }
   }
})

data class NumberMathScenario(
   val expression: String,
   val expected: Any
)
